582	// Per-element Muon apply — canonical scalar body, shared by the scalar tail and
583	// (replicated lane-by-lane) the f32x4 fast-path so both are bit-identical.
584	template <typename ParamT, typename OrthT>
585	__device__ __forceinline__ void muon_apply_elem(
586	    ParamT* __restrict__ param, const OrthT* __restrict__ orth, int64_t i,
587	    float decay, float neg_lr_scale)
588	{
589	    const float p = static_cast<float>(param[i]);
590	    const float x = static_cast<float>(amd::streaming_load(&orth[i]));
591	    amd::streaming_store(&param[i],
592	                         static_cast<ParamT>(p * decay + neg_lr_scale * x));
593	}
