595	template <typename ParamT, typename OrthT>
596	SG_KERNEL_BOUNDS(256, 8) void muon_gfx942_apply_kernel(
597	    ParamT* __restrict__ param, const OrthT* __restrict__ orth,
598	    float decay, float neg_lr_scale, int64_t N)
599	{
600	    // 64-bit grid-stride indexing (Stage 1): cast BEFORE the multiply.
601	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
602	    const int64_t tid    = static_cast<int64_t>(blockIdx.x) * blockDim.x
603	                       + threadIdx.x;
604	
605	    constexpr bool kVecOk =
606	        sizeof(ParamT) == sizeof(float) && sizeof(OrthT) == sizeof(float);
607	    const int64_t n4 = kVecOk ? (N >> 2) : 0;   // number of full float4 groups
608	
609	    using f32x4 = amd::f32x4;
610	    auto* p4 = reinterpret_cast<f32x4*>(param);
611	    const auto* x4 = reinterpret_cast<const f32x4*>(orth);
612	
613	    for (int64_t q = tid; q < n4; q += stride) {
614	        const f32x4 p = p4[q];
615	        const f32x4 x = amd::streaming_load(&x4[q]);   // 128-bit dwordx4 load (orth)
616	        f32x4 po;
617	        for (int l = 0; l < 4; ++l) {
618	            po[l] = p[l] * decay + neg_lr_scale * x[l];
619	        }
620	        amd::streaming_store(&p4[q], po);              // 128-bit dwordx4 store
621	    }
622	
623	    // SCALAR TAIL: the final N%4 elements (and the whole array on fp32 fallback).
624	    for (int64_t i = (n4 << 2) + tid; i < N; i += stride) {
625	        muon_apply_elem(param, orth, i, decay, neg_lr_scale);
626	    }
627	}
